    @EventHandler( payloadType=CreateBIQueryEvent.class )
    public void handle( CreateBIQueryEvent event) {
	    LOGGER.info("handling CreateBIQueryEvent - " + event );
	    BIQuery entity = new BIQuery();
            entity.setBIQueryId( event.getBIQueryId() );
            entity.setName( event.getName() );
            entity.setText( event.getText() );
            entity.setDialect( event.getDialect() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllBIQuery( entity );
    }

