    /**
     * Method to retrieve the BIQuery via an BIQueryPrimaryKey.
     * @param 	id Long
     * @return 	BIQuery
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public BIQuery handle( FindBIQueryQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getBIQueryId() );
    }
    
    /**
     * Method to retrieve a collection of all BIQuerys
     *
     * @param	query	FindAllBIQueryQuery 
     * @return 	List<BIQuery> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<BIQuery> handle( FindAllBIQueryQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindBIQuery,
 * but only if the id matches
 *
 * @param		entity	BIQuery
 */
	protected void emitFindBIQuery( BIQuery entity ) {
		LOGGER.info("handling emitFindBIQuery" );
		
	    queryUpdateEmitter.emit(FindBIQueryQuery.class,
	                            query -> query.getFilter().getBIQueryId().equals(entity.getBIQueryId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllBIQuery
	 * 
	 * @param		entity	BIQuery
	 */
	protected void emitFindAllBIQuery( BIQuery entity ) {
		LOGGER.info("handling emitFindAllBIQuery" );
		
	    queryUpdateEmitter.emit(FindAllBIQueryQuery.class,
	                            query -> true,
	                            entity);
	}

